package guidancecontent

import (
	"io/fs"

	"github.com/jaxxstorm/fed/internal/readiness"
)

// SCN keeps evaluation, pre-change plans, completion and assessment milestones distinct.
func SCN(rules, markdown fs.FS) (readiness.Package, error) {
	return communicationDraft(rules, markdown, "SCN", "significant-change-notification", 81, scnRecipes, []communicationCapability{
		{"scn-change-register", "Significant change classification and milestone history", "Change management owner", "Inventory potential significant changes and their service/customer effects. Record classification rationale, whether the entire offering's certification class changes, change start/finish and assessment-completion milestones, impact analysis, approver and affected controls or KSIs. Link emergency changes to incident records.", "A versioned change register distinguishes not-significant, class-change, routine recurring, transformative and adaptive outcomes and retains the evidence supporting each decision."},
		{"scn-notification-delivery", "Versioned change notification delivery", "Change communications owner", "Identify necessary parties including FedRAMP, using agency customers and agreement-required parties. Locate the package-documented notification mechanism, human-readable/JSON publication locations and delivery history. Connect notices to change and assessment milestones with the business-day calendar used for deadline calculation.", "Each notification can be traced to a change, milestone, exact payload revision, recipient roster, publication location and actual send time."},
	}, []string{"Significant Change", "Certification Class Change", "Routine Recurring Change", "Transformative Change", "Adaptive Change", "All Necessary Parties", "Incident", "Verification", "Validation", "Vulnerability", "Regularly"})
}

var scnRecipes = map[string]communicationRecipe{
	"SCN-FRP-CAP": {purpose: "FedRAMP may impose extra delay or advance approval under a formal Corrective Action Plan or agreement; this is FedRAMP discretion, not a universal provider preapproval duty. The provider-profile inventory excludes this actor-specific rule."},
	"SCN-CSO-EVA": {cap: "scn-change-register", owner: "Change management owner and security architect", purpose: "Classify each potential significant change before selecting the notification path; product labels alone do not determine security impact.", setup: "Build the classification decision tree using the pinned definitions and connect engineering changes to impact analysis, service risk and customer responsibilities.", operate: "Evaluate significance, then whether the offering's certification class changes (requiring new assessment outside SCN), then routine recurring, then transformative, otherwise adaptive. Follow the resulting notification rules. Preserve real examples where available and clearly labeled fictitious examples for demonstrating each type's decision process where needed.", records: "Change descriptions, security/privacy impact analysis, determined types and explanations, resulting notification/assessment paths and at least one decision-process example for each change type, with fictitious examples explicitly labeled.", review: "Trace all potential significant changes from intake through the ordered decision tree. Validate recurrence for routine changes and substantive risk for transformative changes; a class change cannot be processed merely as an adaptive notice.", scope: "All potential significant changes to the offering, including information flows, third-party services and customer configuration responsibilities.", timing: "Retain evaluation and decision dates in relation to planned/actual deployment and applicable notification milestones; EVA supplies no independent numeric review interval.", insufficient: "An unexplained change-type dropdown, blanket classification of all patches as routine or synthetic examples claimed as actual deployments.", trigger: "event"},
	"SCN-CSO-MAR": {cap: "scn-change-register", owner: "Change management owner", purpose: "Keep classification decisions auditable and retrievable for FedRAMP without treating routine email submission as required.", setup: "Choose the evaluation-record repository, retain decision provenance and document how FedRAMP can request and obtain the records.", operate: "Maintain auditable SCN-CSO-EVA evaluation history and make it available when FedRAMP requests it. These records need not be in the certification package by default or continuously emailed to FedRAMP.", records: "Versioned evaluation records with change descriptions, decisions and reasoning; repository access/request instructions and any actual FedRAMP request/response trail.", review: "Retrieve selected evaluation records from their change identifiers and verify attributable decision history. Check response to actual requests separately from repository availability.", scope: "The offering's significant-change evaluation activities, including decisions that do not lead to formal notifications.", timing: "Record decision/revision times and any FedRAMP request and response dates; no extra fixed retention or response deadline is specified by MAR.", insufficient: "Notification copies alone without evaluation rationale or a claim that records exist with no retrieval route.", trigger: "event"},
	"SCN-CSO-INF": {cap: "scn-change-register", owner: "Change communications owner", purpose: "Supply the minimum substantive change information that lets customers understand impact, plans and responsibility changes.", setup: "Map notification fields to the change register, FedRAMP ID, assessor and vulnerability references, customer impact analysis, verification/assessment plan and approver.", operate: "Prepare the notice with the service FedRAMP ID; assessor and related vulnerability where applicable; type and rationale; description and reason; customer impacts and configuration responsibilities; plan/timeline including affected KSI or Rev5-control verification, assessment or validation; business or security impact analysis; and approver name/title.", records: "Recent or explicitly labeled sample notification, field-to-source map, impact-analysis copy, change/assessment timeline, customer responsibility changes, approver attribution and supported conditional-field applicability decisions.", review: "Check every required field for substance against the originating records; test assessor/vulnerability applicability explicitly. A schema-valid notice with placeholders does not establish useful information or actual notification.", scope: "Each Significant Change Notification and the change, customer effects, controls/KSIs and approval it describes.", timing: "Bind notice revision and plan dates to the relevant change phase; deadlines come from the specific adaptive or transformative milestone rules.", insufficient: "A title-only change ticket, a blank schema template, or sample content represented as a sent notice.", trigger: "event"},
	"SCN-CSO-HIS": {cap: "scn-notification-delivery", owner: "Certification data owner", purpose: "Keep a retrievable historical notification series alongside certification data.", setup: "Inventory notification publication locations and configure history preservation without overwriting older notice revisions.", operate: "Keep 12 months of historical Significant Change Notifications available with the service's certification data and document how FedRAMP obtains them.", records: "Dated notification index covering the required history, retained notice revisions and publication/access checks from the certification-data location; documented no-notification intervals where supported by the change register.", review: "Reconcile the notification history with the change register and test retrieval across the 12-month window. An empty directory cannot by itself establish that no notices were due.", scope: "All historical Significant Change Notifications for the offering in the required history window.", timing: "Keep 12 months available; retain notice dates, coverage-window boundaries and the date availability was checked.", insufficient: "Only the latest notice, an inaccessible archive or a retention setting without retrievable history.", trigger: "recurring"},
	"SCN-CSO-HRM": {cap: "scn-notification-delivery", owner: "Certification data owner", purpose: "Make both notifications and related audit records usable by humans and machines.", setup: "Identify human-readable and JSON representations for the entire notification and audit-record inventory, with request/access instructions and sharing decisions.", operate: "Make ALL Significant Change Notifications and related audit records available in both human-readable and JSON formats. Retain the URL or request route and explain material-sharing decisions or policies.", records: "Paired human-readable/JSON exports for notifications and audit records, completeness index, format/content comparison, retrieval route and sharing-policy explanation.", review: "Reconcile both representations to the full inventory and compare semantic content. Machine-readable means JSON here, not a PDF or an arbitrary export format.", scope: "All notification records AND their related audit records, including historical revisions in scope.", timing: "Record export and availability dates and originating record revisions; HRM adds no numeric publication interval.", insufficient: "JSON notices but only PDF audit records, a schema without populated data or inaccessible download links.", trigger: "event"},
	"SCN-CSO-ARI": {cap: "scn-change-register", owner: "Change communications owner", purpose: "Permit useful additional notification information without inventing extra mandatory fields.", setup: "Identify optional explanatory material relevant to customer understanding, such as rollout guidance or additional impact context.", operate: "If elected, include additional relevant information in the notice, keeping it distinguishable from the required minimum and consistent with the change record. Non-election is not a missing required artifact.", records: "Elected supplemental material, its relevance to the identified change and the notice revision carrying it; or the recorded choice not to add material.", review: "Check supplemental statements against change facts and customer impacts. Do not turn this permission into a requirement to add content or substitute it for required information.", scope: "Optional information attached to or included in the identified Significant Change Notification.", timing: "Use the associated notice's revision and milestone; this permission supplies no independent timing obligation.", insufficient: "Unsupported promotional content or treating an optional appendix as proof that required notice fields are complete.", trigger: "event"},
	"SCN-CSO-NOM": {cap: "scn-notification-delivery", owner: "Change communications owner", purpose: "Allow service-appropriate notification methods while keeping the chosen mechanism documented and accessible.", setup: "Choose notification routes based on provider/customer needs and map each route to package instructions and necessary-party access.", operate: "Use the chosen notification mechanisms with clear documentation in the certification package and easy accessibility. Email plus secure upload is a source example, not a mandated product or exclusive method.", records: "Current list of mechanisms, package instructions, necessary-party access checks and actual notification delivery records for the selected routes.", review: "Follow the package instructions as an intended recipient and verify accessibility and actual use. A documented mechanism alone does not prove a particular deadline was met.", scope: "The service's chosen notification mechanisms and necessary-party recipients.", timing: "Retain mechanism/documentation revisions and actual send times; calculate deadlines under the applicable notification rule.", insufficient: "An undocumented email practice, a portal inaccessible to agencies or equating a stored draft with a sent notification.", trigger: "event"},
	"SCN-CSO-EMG": {cap: "scn-change-register", owner: "Incident commander and change management owner", purpose: "Allow emergency execution before advance SCN steps while retaining the mandatory response and post-incident follow-through.", setup: "Link emergency-change procedures to incident handling, necessary-party contacts, retroactive notice preparation and appropriate assessment ownership. Locate the package's emergency procedure documentation.", operate: "When the provider elects emergency execution, record the emergency or incident basis, follow all relevant procedures, notify all necessary parties, retroactively supply ALL SCN materials, and complete appropriate assessment after the incident. Permission to act before advance notice does not waive these follow-up duties.", records: "Incident/emergency basis and timeline, applicable procedure versions and execution records, deployed change, necessary-party notifications and delivery trail, complete retroactive SCN materials, and post-incident assessment scope/results.", review: "Evaluate the emergency basis and each follow-through separately: relevant procedures, notification coverage, retroactive materials and completed appropriate assessment. A closed emergency ticket cannot substitute for an assessment.", scope: "Significant changes executed under the emergency/incident permission, including transformative changes and their necessary-party audience.", timing: "Preserve emergency, execution, notification, retroactive-material and post-incident assessment dates. EMG requires assessment after the incident but does not specify a new numeric emergency deadline.", insufficient: "Emergency labeling alone, an incident report without SCN materials or an assessment plan represented as completed assessment.", trigger: "event"},
	"SCN-RTR-NNR": {cap: "scn-change-register", owner: "Change management owner", purpose: "Avoid formal SCN notices for genuinely routine recurring changes while preserving the evaluation that supports the exemption.", setup: "Map recurring operational and remediation activities to their established processes and actual history; distinguish unusual replacements or migrations from regular maintenance.", operate: "Apply the routine recurring notification exemption to changes supported by regular, routine recurrence. Preserve SHOULD NOT and document any weighed decision to issue formal notices in security documentation; continue retaining classification audit records.", records: "Recurring process/run history, change descriptions and classification rationale demonstrating regular recurrence and mature risk handling; any documented decision to send formal notice despite the recommendation.", review: "Compare the actual activity with recurrence history and the definition. A security fix is not automatically routine; a one-off fleet replacement cannot be made routine by its label.", scope: "Changes classified as routine recurring within ongoing operations or vulnerability mitigation/remediation.", timing: "Retain recurring-process intervals and execution dates as evidence of recurrence; this exemption does not create a formal notification deadline.", insufficient: "A routine tag without operating history or absence of a notice mistaken for proof of valid exemption.", trigger: "event"},
	"SCN-ADP-NTF": scnNotice("adaptive completion", "Record adaptive classification and the actual change finish milestone; reconcile new risks and vulnerabilities with the impact analysis.", "Notify all necessary parties within 10 business days after finishing the adaptive change, including any applicable new-risk/vulnerability summary and the general SCN information.", "Actual adaptive-change finish time, delivered notice and recipient roster, new-risk/vulnerability summary or justified nonapplicability, and business-day calculation.", "Use the actual finish milestone and the within-10-business-days bound. Do not start the clock at a later report-writing or assessment date."),
	"SCN-TRF-NIP": scnNotice("transformative initial plans", "Identify the transformative classification, planned start, initial plan and likely security impacts or changes in risk before scheduling deployment.", "Notify all necessary parties of initial transformative plans at least 30 business days before starting, including likely security impacts or changes in risk.", "Initial plan/impact summary, exact sent notice, necessary-party recipient roster, send timestamp, planned and actual start dates and business-day calculation.", "Measure at least 30 business days from actual notification to start; a plan created earlier but sent later does not satisfy advance notification."),
	"SCN-TRF-NFP": scnNotice("transformative final plans", "Compare final deployment plans against all previously supplied information and identify updates before the planned start.", "Notify all necessary parties of final transformative plans at least 10 business days before starting, including updates to all previously sent information.", "Initial and final notice revisions, comparison of all previously sent information, final plan, recipient/delivery trail, start dates and business-day calculation.", "Measure at least 10 business days before starting, separately from the initial-plan notice; retain changes to the start date and notification revisions."),
	"SCN-TRF-NAF": scnNotice("transformative change completion", "Identify actual deployment completion independently from later verification/assessment completion and compare previous notice content to deployed reality.", "Notify all necessary parties within 5 business days after finishing the transformative change, updating all previously sent information.", "Actual change-finish milestone, deployed change records, previous/current notice comparison, necessary-party delivery timestamps and business-day calculation.", "Use within 5 business days after change finish; do not defer this notice until assessment is complete."),
	"SCN-TRF-NAV": scnNotice("transformative verification completion", "Identify completion of verification, assessment and/or validation and obtain updated risks, vulnerabilities and the assessment report where applicable.", "Notify all necessary parties within 5 business days after completing verification, assessment and/or validation. Include updates to all previously sent information, applicable new risks/vulnerabilities and a security assessment report copy where applicable.", "Verification/assessment/validation completion evidence and results, applicable assessment report copy, new-risk/vulnerability summary, prior/current notice comparison, delivery trail and business-day calculation.", "Use within 5 business days after verification/assessment/validation completion, separately from deployment completion; preserve the basis for the chosen milestone."),
	"SCN-TRF-UPD": {cap: "scn-change-register", owner: "Service documentation owner", purpose: "Make user-facing service documentation and other materials reflect the transformative change.", setup: "Map the transformative change to user guides, marketplace information and other affected service documentation, assigning content owners and publication locations.", operate: "Publish the updated service documentation and other affected materials within 30 business days after finishing the transformative change. If no updates were required, explain how that was determined. This rule does not itself require updating the SSP or certification package.", records: "Actual transformative-change finish date, document-impact map, before/after service-documentation revisions, publication timestamps and business-day calculation; reasoned no-update determination where applicable.", review: "Compare customer-facing instructions and descriptions with the deployed change and verify publication rather than draft completion. Keep package-maintenance obligations separate.", scope: "Service documentation and other affected published materials for the identified transformative change.", timing: "Within 30 business days after finishing the transformative change; retain finish and publication dates and the calendar basis.", insufficient: "A documentation ticket marked complete without publication or an updated security package with stale user guides.", trigger: "event"},
	"SCN-TRF-TPR": {cap: "scn-change-register", owner: "Security architect and assessor liaison", purpose: "Use assessor judgment for transformative-change security decisions that need human validation, rather than forcing blanket reassessment of automated facts.", setup: "Identify planned transformative scope and impact, enumerate security decisions requiring human validation and distinguish them from machine-verifiable facts.", operate: "Where human validation is necessary, engage a third-party assessor before the change starts to review planned scope and impact, limiting the review to security decisions requiring human validation. Document the weighed recommendation decision, including why no assessor was engaged when applicable.", records: "Human-validation necessity analysis, planned scope/impact, assessor engagement and dated report or explanation for non-engagement, selected security decisions, start milestone and recommendation decision in security documentation.", review: "Check necessity, review scope and completion relative to start; avoid equating absence of an assessor with a justified no-human-validation determination.", scope: "The planned transformative change's security decisions that require human validation.", timing: "Before starting the transformative change when human validation is necessary; no numeric lead time is added.", insufficient: "A generic assessor contract without scope/impact review, review after deployment or unsupported assertion that automation eliminates all human decisions.", trigger: "event"},
}

func scnNotice(milestone, setup, operate, records, timing string) communicationRecipe {
	operate += " Update FedRAMP Certification Data with the notification, preserving the structured source's notification target as well as delivery to necessary parties."
	records += " Retain the corresponding Certification Data update revision and publication timestamp."
	return communicationRecipe{cap: "scn-notification-delivery", owner: "Change communications owner", purpose: "Deliver attributable, complete notification for the " + milestone + " milestone to all necessary parties.", setup: setup, operate: operate, records: records + " Include the general SCN-CSO-INF information and retain actual or explicitly labeled sample status. Where no relevant notices have been sent, the source artifact exception permits no historical example; the change register must support that history.", review: "Reconcile the " + milestone + " milestone with the delivered payload and necessary-party roster, and independently assess content completeness and business-day timing. Retain missing recipients, late delivery and unsupported event dates as findings.", scope: "Every applicable " + milestone + " event for the offering, FedRAMP, all using agency customers and additional agreement-required parties.", timing: timing, insufficient: "A draft notice, portal upload without recipient notification, sample claimed as actual delivery or a send date without its triggering milestone.", trigger: "event"}
}
